#!/usr/bin/env bash
set -Eeuo pipefail
VERSION="2.0.0"
APP_ROOT="/opt/veloraos"
PAYLOAD_DIR="$(mktemp -d /tmp/veloraos-update-payload.XXXXXX)"
PAYLOAD_ARCHIVE="$PAYLOAD_DIR/payload.tar.gz"
PAYLOAD_SHA256="f35d3a5b97276e1020b4aea00d43cad7d39d6276b08e98e49134acd897530743"
PAYLOAD_BYTES="1890217"
SUCCESS=0
log(){ printf '[VeloraOS update %s] %s\n' "$VERSION" "$*"; }
die(){ printf '[Error] %s\n' "$*" >&2; exit 1; }
cleanup(){ rm -rf "$PAYLOAD_DIR" 2>/dev/null || true; }
finish(){ local code=$?; trap - EXIT INT TERM; cleanup; exit "$code"; }
trap finish EXIT INT TERM
usage(){ cat <<'USAGE'
Usage: sudo bash VeloraOS-Update-2.0.0-Aurora-Redesign.sh --non-interactive

Migrates VeloraOS 1.16.0 or newer to VeloraOS 2.0.0 in place while preserving
accounts, chats, Knowledge, licensing, device identity, Continuity keys,
Time Machine snapshots, plugins, flows, activity history, Local Intelligence
configuration, settings and rollback state.
USAGE
}
NON_INTERACTIVE=0
for arg in "$@"; do case "$arg" in --non-interactive) NON_INTERACTIVE=1 ;; -h|--help) usage; exit 0 ;; *) die "Unknown option: $arg" ;; esac; done
[[ "$NON_INTERACTIVE" == "1" || "${VELORAOS_NONINTERACTIVE:-0}" == "1" ]] || die 'This updater requires --non-interactive.'
[[ ${EUID:-$(id -u)} -eq 0 ]] || die 'This updater must run as root.'
[[ -d "$APP_ROOT" && -f "$APP_ROOT/app/main.py" ]] || die 'The installed VeloraOS layout is incomplete.'
[[ -r /etc/veloraos/license ]] || die 'The existing VeloraOS licence file is missing.'
for command in awk base64 tr sha256sum stat tar bash hostname; do command -v "$command" >/dev/null 2>&1 || die "Required command is missing: $command"; done
log 'Extracting the verified embedded VeloraOS 2 application payload.'
awk '{line=$0; sub(/\r$/, "", line)} line=="__VELORA_PAYLOAD_BELOW__" {found=1; next} found {print} END {if (!found) exit 2}' "$0" | tr -d '[:space:]' | base64 --decode > "$PAYLOAD_ARCHIVE" || die 'The embedded application payload is missing or is not valid Base64. Download the raw script again.'
[[ "$(stat -c '%s' "$PAYLOAD_ARCHIVE")" == "$PAYLOAD_BYTES" ]] || die 'The embedded application payload size does not match.'
ACTUAL_PAYLOAD_SHA256="$(sha256sum "$PAYLOAD_ARCHIVE" | awk '{print $1}')"
[[ "$ACTUAL_PAYLOAD_SHA256" == "$PAYLOAD_SHA256" ]] || die 'The embedded application payload checksum does not match; the script is truncated or modified.'
tar -tzf "$PAYLOAD_ARCHIVE" >/dev/null || die 'The embedded application payload is not a valid gzip archive.'
tar -xzf "$PAYLOAD_ARCHIVE" -C "$PAYLOAD_DIR"
[[ -f "$PAYLOAD_DIR/app/main.py" && -f "$PAYLOAD_DIR/app/updater.py" && -f "$PAYLOAD_DIR/app/time_machine.py" && -f "$PAYLOAD_DIR/app/continuity.py" && -f "$PAYLOAD_DIR/app/activity_center.py" && -f "$PAYLOAD_DIR/app/flow.py" && -f "$PAYLOAD_DIR/app/plugin_sdk.py" && -f "$PAYLOAD_DIR/app/local_intelligence.py" && -f "$PAYLOAD_DIR/app/static/app.js" && -f "$PAYLOAD_DIR/app/static/app-200000.js" && -f "$PAYLOAD_DIR/app/static/style-200000.css" && -f "$PAYLOAD_DIR/installer/veloraos-install.sh" && -f "$PAYLOAD_DIR/installer/veloraos-update-runner.py" && -f "$PAYLOAD_DIR/veloraos.service" && -f "$PAYLOAD_DIR/veloraos-update.service" && -f "$PAYLOAD_DIR/veloraos-time-machine.service" && -f "$PAYLOAD_DIR/veloraos-recovery.service" ]] || die 'The embedded application payload is incomplete.'
grep -Fq 'VERSION = "2.0.0"' "$PAYLOAD_DIR/app/main.py" || die 'The embedded payload has the wrong VeloraOS version.'
grep -Fq 'Velora Search' "$PAYLOAD_DIR/app/static/app-200000.js" || die 'Velora Search is missing from the embedded application payload.'
grep -Fq 'v2-sidebar' "$PAYLOAD_DIR/app/static/app-200000.js" || die 'The VeloraOS 2 workspace shell is missing from the embedded application payload.'
grep -Fq 'v2-today-hero' "$PAYLOAD_DIR/app/static/app-200000.js" || die 'The VeloraOS 2 Today workspace is missing from the embedded application payload.'
grep -Fq 'appearance.midnight' "$PAYLOAD_DIR/app/static/app-200000.js" || die 'The Midnight appearance is missing from the embedded application payload.'
grep -Fq 'function activityPage()' "$PAYLOAD_DIR/app/static/app-200000.js" || die 'Activity Centre is missing from the embedded application payload.'
grep -Fq 'function flowPage()' "$PAYLOAD_DIR/app/static/app-200000.js" || die 'Velora Flow is missing from the embedded application payload.'
grep -Fq 'function pluginsPage()' "$PAYLOAD_DIR/app/static/app-200000.js" || die 'Plugin SDK is missing from the embedded application payload.'
grep -Fq 'function intelligencePage()' "$PAYLOAD_DIR/app/static/app-200000.js" || die 'Local Intelligence is missing from the embedded application payload.'
chmod 0755 "$PAYLOAD_DIR/installer/veloraos-install.sh"
DEVICE_NAME="$(cat /etc/veloraos/device-name 2>/dev/null || hostname)"
export VELORAOS_LICENSE_FILE=/etc/veloraos/license
printf '%s\n' "$DEVICE_NAME" | /bin/bash "$PAYLOAD_DIR/installer/veloraos-install.sh" --replace --skip-ollama
SUCCESS=1
log 'VeloraOS 2.0.0 installed successfully.'
exit 0
